#[test]
fn test_gpx_strict_topografix_xsd_validation() {
    let datasets = vec![
        ("canonical_cruise", canonical_cruise_dataset()),
        ("multi_segment", multi_segment_dataset()),
        ("boundary_extremum", boundary_extremum_dataset()),
        ("special_characters", special_characters_dataset()),
        ("empty", empty_dataset()),
    ];

    let xsd_path = std::path::Path::new("/tmp/schemas/gpx.xsd");
    if !xsd_path.exists() {
        return;
    }

    let exporter = GpxExporter::default();

    for (name, ds) in datasets {
        let gpx_str = exporter.export_to_string(&ds).unwrap();
        let mut temp_file = tempfile::NamedTempFile::new().expect("Failed to create temp file");
        std::io::Write::write_all(&mut temp_file, gpx_str.as_bytes()).expect("Write temp GPX failed");

        let output = std::process::Command::new("xmllint")
            .arg("--noout")
            .arg("--schema")
            .arg(xsd_path)
            .arg(temp_file.path())
            .output();

        if let Ok(out) = output {
            assert!(
                out.status.success(),
                "Dataset '{name}' failed TopoGrafix GPX 1.1 XSD validation:\n{}",
                String::from_utf8_lossy(&out.stderr)
            );
        }
    }
}
"

