    height_m: f64,
    fly_time_s: f64,
    speed_mps: f64,
    is_motor_up: bool,
    mode_u8: u8,
) -> [u8; 53] {
    let mut buf = [0u8; 53];
    LittleEndian::write_f64(&mut buf[0..8], lon_deg.to_radians());
    LittleEndian::write_f64(&mut buf[8..16], lat_deg.to_radians());
    LittleEndian::write_i16(&mut buf[16..18], (height_m * 10.0).round() as i16);
    LittleEndian::write_i16(&mut buf[18..20], (speed_mps * 10.0).round() as i16);
    if is_motor_up {
        buf[30] |= 0x08;
    }
    let status = 0x80u32 | (mode_u8 as u32 & 0x7F);
    LittleEndian::write_u32(&mut buf[32..36], status);
